#endif

const int maxn = (1<<20)+7;
const int maxk = 20;
const int inf = (1e9)+7;
const LL LLinf = ((LL)1e18)+7LL;
const LD eps = 1e-9;
const LL mod = 1e9+7;

// ***************************** CODE ***************************** //

int tab[maxk][maxk];
int elo[maxk][maxk];
int maska[maxn];

LL dp[maxn][2];

int daj(VPII kraw, bool f)
{
  int mask = 0;
  for(int i = 0;i < SZ(kraw);i++)
    for(int j = i + 1;j < SZ(kraw);j++)
      if(kraw[i].fi != kraw[j].fi and kraw[i].se != kraw[j].se)
        for(int k = j + 1;k < SZ(kraw);k++)
          if(kraw[i].fi != kraw[k].fi and kraw[j].fi != kraw[k].fi and kraw[i].se != kraw[k].se and kraw[j].se != kraw[k].se)
            mask |= maska[(f ? 126 : 0) ^ ((1<<kraw[i].se) + (1<<kraw[j].se) + (1<<kraw[k].se))];
  return mask;
}

LL pot(LL a, LL w)
{
  if(!w) return 1;
  LL b = pot(a, w / 2);
  b = b * b % mod;
  if(w & 1)
    b = b * a % mod;
  return b;
}

int main()
{
